// V17.7.4 — SERVERLESS Usage Analytics (provider "repository") and the registry-free build.
// (1) version / release note / UI baseline of V17.7.3, (2) the cryptography (password-wrapped private key, hybrid encryption, tamper / downgrade / wrong-key cases), (3) the strict validator and the aggregation are
// IDENTICAL to the analytics service (the same events give the same dashboard), (4) the device side (encrypted write, failure results), (5) the administrator side (set-up, unlock, change password, rotate keys,
// compaction, retention) over an in-memory repository AND over a real local HTTP stand-in of the GitHub contents API, (6) configuration, (7) privacy / source guarantees, (8) publication excludes the analytics folder,
// (9) the build needs only Node: the committed, checksum-pinned TypeScript, the workflows, the hygiene check, (10) documentation.
// Passwords are synthetic example values. The key file uses the MINIMUM allowed PBKDF2 cost (600 000 iterations) — the policy itself is under test, so it is never lowered.
import test from 'node:test'; import assert from 'node:assert/strict';
import { readFileSync, existsSync, readdirSync, mkdtempSync, rmSync, cpSync, writeFileSync, statSync, mkdirSync } from 'node:fs'; import { join, dirname } from 'node:path'; import { tmpdir } from 'node:os'; import { createHash } from 'node:crypto'; import { spawnSync } from 'node:child_process';
import { imp } from './helpers.mjs'; import { CURRENT_VERSION, PREVIOUS_VERSION } from './support/version.mjs'; import { createGithubStub } from './support/analytics-github-stub.mjs';
const root = join(dirname(new URL(import.meta.url).pathname), '..'); const src = (p) => readFileSync(join(root, p), 'utf8'); const strip = (s) => s.replace(/\/\*[\s\S]*?\*\/|\/\/.*$/gm, '');
const F = await imp('v17/sync/schemaFormat.js'); const NLU = await imp('v17/engines/nluEngine.js'); const C = await imp('v17/services/analyticsCrypto.js'); const R = await imp('v17/services/analyticsRepo.js'); const AG = await imp('v17/services/analyticsAggregate.js');
const G = await imp('v17/services/githubClient.js'); const TR = await imp('v17/services/analyticsTracker.js'); const CFG = await imp('v17/services/analyticsConfig.js'); const { memoryStore } = await imp('services/storage.js');
const SV = await import(new URL('../server/analytics-service.mjs', import.meta.url)); const PUB = await import(new URL('../scripts/publish-data.mjs', import.meta.url)); const TC = await import(new URL('../scripts/toolchain.mjs', import.meta.url));
const NOTE = 'V17.7.4 makes Usage Analytics deployable without a server or cloud credentials. Analytics data is encrypted on the device and can be read only in the Analytics dashboard after administrator authentication. SQL Assistant continues to capture usage metadata only and does not capture SQL content, credentials, database results, or customer data.';
const PW = 'SYNTHETIC-correct-horse-battery-42'; const PW2 = 'SYNTHETIC-another-long-passphrase-77'; const BASE = 'sql-assistant-data/analytics'; const P = R.analyticsPaths(BASE); const DAY = 86_400_000;
const UID = (c) => c.repeat(32); const SID = (n) => String(n).padStart(24, '0'); let counter = 0; const eid = () => `e${String(++counter).padStart(10, '0')}x`; const at = (s) => Date.parse(s);
const ev = (o) => ({ v: 1, eid: eid(), uid: UID('a'), sid: SID(1), ver: '17.7.4', ts: at('2026-11-09T10:00:00Z'), t: 'session_start', ...o });
const ADMIN = await C.createAdminKeyFile(PW); // ONE derivation shared by many tests (each test builds its own repository around it)
const KEYFILE = `${JSON.stringify(ADMIN.file, null, 2)}\n`; const PUBFILE = R.publicKeyFileText(ADMIN.current, '2026-11-01T00:00:00.000Z');
/** a fresh in-memory repository that is already set up, its IO and an unlocked session (no extra PBKDF2) */
function world(extra = {}) { const mem = G.memoryRepository({ [P.adminKey]: KEYFILE, [P.publicKey]: PUBFILE, ...extra }); const io = R.repoIOFrom(mem); const session = { io, base: BASE, unlocked: ADMIN, adminSha: mem.files.get(P.adminKey).sha, cache: new Map() }; return { mem, io, session }; }
const sinkAt = (io, nowMs, extra = {}) => new R.RepositoryTelemetrySink({ io: () => io, base: BASE, pinned: null, now: () => nowMs, ...extra });
const files = (mem, dir) => [...mem.files.keys()].filter((k) => k.startsWith(`${dir}/`));
const strictSummary = (r) => { assert.equal(r.ok, true, JSON.stringify(r)); const { generatedAt, ...d } = r.data; return d; };

// ───────────────────────────────────────── 1. version, release note, UI baseline
test('V17.7.4 version stamps (historical release): its documents are kept, README and About still describe it, and the current stamp is a valid 17.7.x (the current-version assertions live in test/v1775.test.mjs)', () => {
  assert.match(CURRENT_VERSION, /^17\.7\.\d+$/); assert.equal(JSON.parse(src('package.json')).version, CURRENT_VERSION); assert.equal(F.APP_VERSION, CURRENT_VERSION); assert.equal(F.WRITER_LABEL, `SQL Assistant ${CURRENT_VERSION}`); assert.equal(NLU.NLU_ENGINE_VERSION, `offline-nlu-${CURRENT_VERSION}`);
  assert.match(src('src/ui/pages/other.ts'), /<li><strong>17\.7\.4<\/strong>.*<li><strong>17\.7\.3<\/strong>.*<li><strong>17\.7\.2<\/strong>/s); assert.match(src('README.md'), /^## SQL Assistant — V17\.7\.\d+/m); assert.match(src('README.md'), /What (?:is|was) new in V17\.7\.4/); assert.match(src('README.md'), /What was new in V17\.7\.3/);
  if (existsSync(join(root, 'release/version.json'))) assert.equal(JSON.parse(src('release/version.json')).version, CURRENT_VERSION); for (const f of ['dist/index.html', 'index.html', 'release/index.html']) if (existsSync(join(root, f))) { const h = src(f); assert.ok(h.includes(`SQL Assistant ${CURRENT_VERSION}`), f); assert.ok(h.includes(`Loading SQL Assistant ${CURRENT_VERSION}`), f); assert.ok(!/SQL Assistant 17\.7\.3/.test(h), `${f}: no stale version`); }
  assert.ok(!/17\.7\.3/.test(JSON.parse(src('package.json')).version) && !/17\.7\.3/.test(strip(src('src/v17/sync/schemaFormat.ts'))) && !/17\.7\.3/.test(strip(src('src/v17/engines/nluEngine.ts'))), 'no stale active-version reference');
  for (const d of ['CHANGELOG_V17.7.4.md', 'RELEASE_NOTES_V17.7.4.md', 'TEST_REPORT_V17.7.4.md', 'VERIFICATION_REPORT_V17.7.4.md', 'REGRESSION_BASELINE_V17.7.4.md', 'ROLLBACK_V17.7.4.md', 'CHANGED_FILES_V17.7.4.md', 'ANALYTICS_SERVERLESS.md', 'ANALYTICS.md', 'CHANGELOG_V17.7.3.md', 'ROLLBACK_V17.7.3.md']) assert.ok(existsSync(join(root, 'docs', d)), d);
  assert.match(src('docs/ROLLBACK_V17.7.4.md'), /SQL-Assistant-V17\.7\.3\.zip/); assert.equal(JSON.parse(src('package.json')).devDependencies.typescript, '5.8.3'); assert.ok(!JSON.parse(src('package.json')).dependencies, 'no runtime dependency at all'); assert.equal(JSON.parse(src('package.json')).productName, 'SQL Assistant');
});
