  for (const f of ['docs/RELEASE_NOTES_V17.7.4.md', 'src/ui/pages/other.ts', 'src/ui/pages/analyticsPage.ts', 'README.md', 'docs/CHANGELOG_V17.7.4.md']) assert.ok(src(f).includes(NOTE), f); const page = await imp('ui/pages/analyticsPage.js').catch(() => null); if (page) assert.equal(page.ANALYTICS_RELEASE_NOTE_1774, NOTE);
  assert.ok(src('src/ui/pages/analyticsPage.ts').includes('V17.7.3 introduces optional Usage Analytics'), 'the V17.7.3 constant is kept (its tests pin it)');
