  push('2026-10-31T23:50:00Z', { uid: UID('c'), sid: SID(13) }); push('2026-10-31T23:55:00Z', { t: 'active', uid: UID('c'), sid: SID(13), ms: 300_000 }); push('2026-11-01T00:10:00Z', { t: 'active', uid: UID('c'), sid: SID(13), ms: 300_000 }); push('2026-11-03T09:00:00Z', { sid: SID(14) });
  const sorted = [...E].sort((a, b) => a.ts - b.ts); const whole = new AG.UsageModel(); for (const e of sorted) whole.addEvent(e);
