  const parsed = AG.parseRollup(JSON.parse(JSON.stringify(roll))); const rest = new AG.UsageModel(); rest.addRollup(parsed); for (const e of sorted.filter((x) => x.ts >= at('2026-11-01T00:00:00Z'))) rest.addEvent(e);
