  const hostile = AG.parseRollup({ month: '2026-10', days: { '2026-10-05': { sessions: -5, activeMs: 'x', users: { notakey: { s: 1, a: 1 }, ['a'.repeat(16)]: { s: 1e99, a: 5 } }, features: { evil: 99, about: 3 }, versions: { 'SELECT *': { s: 1, u: [] }, '1.0': { s: 2, u: ['zz', 'b'.repeat(16)] } }, gen: { ok: 'a', fail: 2 } }, '2026-09-05': { sessions: 9 }, 'junk': 1 }, sessions: { zz: {}, [SID(1)]: { f: 1, a: 2, u: 'a'.repeat(16), l: 3 } }, merged: ['x', 'a'.repeat(32)] });
