  const text = mem.files.get(writes[0].p).text; for (const w of ['octocat', UID('d'), 'describe-read-only', 'generation', 'feature', 'sid', '"ts"', events[0].eid, '17.7.4']) assert.ok(!text.includes(w), `"${w}" is not readable`); assert.equal(Object.keys(JSON.parse(text)).sort().join(), 'ct,epk,format,iv,kid,v');
  await sinkAt(io, NOW).send([ev({})]); await sinkAt(io, NOW).send([ev({}), ev({}), ev({})]); const names = files(mem, `${BASE}/events/2026-11-09`); assert.equal(names.length, 3, 'one file per batch — nothing links two batches of one device'); assert.equal(new Set(names).size, 3); const sizes = names.map((n) => mem.files.get(n).text.length); assert.ok(Math.max(...sizes) - Math.min(...sizes) < 40, 'batches of 1 and 3 small events have the same size (padding)');
  const s = await sinkAt(io, at('2026-12-02T00:00:00Z')).send([ev({})]); assert.equal(s.ok, true); assert.equal(files(mem, `${BASE}/events/2026-12-02`).length, 1, 'the folder is the UTC day the batch was written (GitHub lists at most 1000 files of a folder)');
