test('V17.7.4 sink — every problem is a RESULT for the tracker (queue + retry), never an exception: no repository, not set up, no write access, wrong token, repository missing, network, name collision', async () => {
  const NOW = at('2026-11-09T10:00:00Z'); const one = [ev({})]; const kinds = { permission: 'no-write-access', auth: 'no-write-access', 'pat-insufficient': 'no-write-access', signin: 'no-write-access', 'not-found': 'repository-unavailable', config: 'repository-unavailable', network: 'network', timeout: 'timeout', http: 'http' };
  assert.deepEqual(await new R.RepositoryTelemetrySink({ io: () => null, base: BASE, pinned: null, now: () => NOW }).send(one), { ok: false, permanent: false, reason: 'no-repository', retryAfterMs: 900_000 });
  const empty = R.repoIOFrom(G.memoryRepository({})); assert.deepEqual(await sinkAt(empty, NOW).send(one), { ok: false, permanent: false, reason: 'not-set-up', retryAfterMs: 600_000 });
  for (const [k, reason] of Object.entries(kinds)) { const { io } = world(); const bad = { ...io, write: async () => { throw new G.RepositoryError('x', k, 403); } }; const r = await sinkAt(bad, NOW).send(one); assert.equal(r.ok, false); assert.equal(r.permanent, false); assert.equal(r.reason, reason, k); if (reason === 'no-write-access') assert.equal(r.retryAfterMs, 3_600_000, 'an hour, not a retry storm'); }
  { const { io } = world(); let n = 0; const col = { ...io, write: async (p, t, s, m) => { n += 1; if (n === 1) throw new G.RepositoryError('exists', 'conflict', 422); return io.write(p, t, s, m); } }; assert.deepEqual(await sinkAt(col, NOW).send(one), { ok: true }, 'a name collision is retried once with a new random name'); assert.equal(n, 2); }
  { const { io } = world(); const boom = { ...io, write: () => { throw new Error('sync boom'); }, read: () => { throw new Error('boom'); } }; const r = await sinkAt(boom, NOW).send(one); assert.equal(r.ok, false); }
  { const { io } = world(); const damaged = R.repoIOFrom(G.memoryRepository({ [P.publicKey]: '{"format":"sqla-analytics-public-key"' })); assert.equal((await sinkAt(damaged, NOW).send(one)).reason, 'not-set-up', 'a damaged public-key file is "not set up", not a crash'); }
  { const { mem, io } = world(); const other = await C.createAdminKeyFile(PW2); const forged = { ...ADMIN.current, kid: 'forgedkid1234' }; const pinnedBad = new R.RepositoryTelemetrySink({ io: () => io, base: BASE, pinned: forged, now: () => NOW }); assert.equal((await pinnedBad.send(one)).ok, false, 'an invalid pinned key is never used'); const pin = new R.RepositoryTelemetrySink({ io: () => io, base: BASE, pinned: other.current, now: () => NOW }); assert.equal((await pin.send(one)).ok, true); const f = files(mem, `${BASE}/events`)[0]; assert.equal(JSON.parse(mem.files.get(f).text).kid, other.current.kid, 'a PINNED public key wins over the key file in the repository'); }
  { const { io } = world(); const s = sinkAt(io, NOW); assert.equal((await s.send(one)).ok, true); const down = { ...io, read: async () => { throw new G.RepositoryError('x', 'network') } }; const s2 = new R.RepositoryTelemetrySink({ io: () => down, base: BASE, pinned: null, now: () => NOW }); assert.equal((await s2.send(one)).ok, false); }
});
test('V17.7.4 sink + tracker — the tracker queues what the sink could not write and retries after the time the sink asks for (no write access → an hour, not a storm); it never throws into the application', async () => {
  const store = memoryStore(); const clock = { mono: 0, wall: at('2026-11-09T10:00:00Z') }; let result = { ok: false, permanent: false, reason: 'no-write-access', retryAfterMs: 3_600_000 }; let calls = 0; const sink = { send: async () => { calls += 1; return result; } };
  const tr = new TR.AnalyticsTracker({ config: { inactivityTimeout: 300, collectUserIdentity: false, applicationVersion: '17.7.4' }, sink, store, mono: () => clock.mono, wall: () => clock.wall, identity: () => null }); tr.start(true, true); tr.feature('about');
  await tr.flush(); assert.equal(calls, 1); clock.wall += 30 * 60_000; await tr.flush(); assert.equal(calls, 1, 'after 30 minutes: still waiting'); clock.wall += 31 * 60_000; result = { ok: true }; await tr.flush(); assert.equal(calls, 2, 'after the hour: tried again'); assert.equal(tr.stats().queued, 0);
  for (const bad of [Infinity, -5, 1e12]) { const t2 = new TR.AnalyticsTracker({ config: { inactivityTimeout: 300, collectUserIdentity: false, applicationVersion: '17.7.4' }, sink: { send: async () => ({ ok: false, permanent: false, reason: 'x', retryAfterMs: bad }) }, store: memoryStore(), mono: () => 0, wall: () => clock.wall, identity: () => null }); t2.start(true, true); await assert.doesNotReject(t2.flush()); }
});

