test('V17.7.4 change password — the key file is re-wrapped (same key pair): the old password stops working, the new one opens ALL earlier data; a weak / unchanged / wrong-current password changes nothing; a concurrent change is a conflict', async () => {
  const { mem, io, session } = world(); const NOW = at('2026-11-09T12:00:00Z'); await sinkAt(io, NOW).send([ev({}), ev({ t: 'feature', f: 'about' })]); const before = mem.files.get(P.adminKey).text;
  for (const [cur, nw, kind] of [['wrong-wrong-wrong-1', PW2, 'invalid-password'], [PW, 'short', 'weak-password'], [PW, PW, 'weak-password'], [PW, 'aaaaaaaaaaaaaaaa', 'weak-password']]) { const r = await R.changePasswordRepo(session, cur, nw); assert.deepEqual([r.ok, r.kind], [false, kind], `${cur}/${nw}`); assert.equal(mem.files.get(P.adminKey).text, before, 'nothing was written'); }
  const ok = await R.changePasswordRepo(session, PW, PW2); assert.equal(ok.ok, true); assert.notEqual(mem.files.get(P.adminKey).text, before); assert.ok(!mem.files.get(P.adminKey).text.includes(PW2));
  assert.equal((await R.unlockAnalyticsRepo(io, BASE, PW)).kind, 'invalid-password', 'the old password no longer works'); const again = await R.unlockAnalyticsRepo(io, BASE, PW2); assert.equal(again.ok, true); const d = strictSummary(await R.loadSummaryRepo(again.session, '2026-11-01', '2026-11-09', NOW, 400)); assert.equal(d.features[0].id, 'about', 'data written BEFORE the change is still readable');
  const stale = { ...again.session }; await R.changePasswordRepo(again.session, PW2, 'SYNTHETIC-third-long-passphrase-9'); const clash = await R.changePasswordRepo({ ...stale, io: { ...io, read: async (p) => (p === P.adminKey ? { text: mem.files.get(p).text, sha: 'stale-sha' } : io.read(p)) } }, PW2, PW); assert.ok(['conflict', 'invalid-password'].includes(clash.kind), clash.kind);
});
test('V17.7.4 rotate keys — a new pair becomes current and its public key is published; batches written before stay readable; after rotation new batches use the new key; an interrupted publish is reported and can be repeated', async () => {
  const { mem, io, session } = world(); const NOW = at('2026-11-09T12:00:00Z'); await sinkAt(io, NOW).send([ev({ sid: SID(31) }), ev({ t: 'feature', f: 'about', sid: SID(31) })]); const oldKid = ADMIN.current.kid;
  assert.equal((await R.rotateKeysRepo(session, 'wrong-wrong-wrong-1')).kind, 'invalid-password'); const rot = await R.rotateKeysRepo(session, PW); assert.equal(rot.ok, true); assert.notEqual(rot.pin.kid, oldKid); assert.equal(JSON.parse(mem.files.get(P.publicKey).text).current.kid, rot.pin.kid); assert.equal(JSON.parse(mem.files.get(P.adminKey).text).keys.length, 2);
  await sinkAt(io, NOW + 1000).send([ev({ sid: SID(32) }), ev({ t: 'feature', f: 'sync', sid: SID(32) })]); const kids = files(mem, `${BASE}/events`).map((f) => JSON.parse(mem.files.get(f).text).kid).sort(); assert.deepEqual(kids, [oldKid, rot.pin.kid].sort());
  const u = await R.unlockAnalyticsRepo(io, BASE, PW); assert.equal(u.ok, true); assert.equal(u.session.unlocked.keys.size, 2); const d = strictSummary(await R.loadSummaryRepo(u.session, '2026-11-01', '2026-11-09', NOW, 400)); assert.equal(d.kpi.totalSessions, 2, 'old and new batches are both read'); assert.deepEqual(d.features.map((f) => f.id).sort(), ['about', 'sync']);
  const m2 = G.memoryRepository({ [P.adminKey]: KEYFILE, [P.publicKey]: PUBFILE }); let n = 0; const flaky = R.repoIOFrom({ ...m2, write: async (p, t, s, m) => { n += 1; if (p === P.publicKey) throw new G.RepositoryError('x', 'network'); return m2.write(p, t, s, m); } }); const s2 = { io: flaky, base: BASE, unlocked: ADMIN, adminSha: m2.files.get(P.adminKey).sha, cache: new Map() }; const partial = await R.rotateKeysRepo(s2, PW); assert.deepEqual([partial.ok, partial.kind], [false, 'partial']); assert.match(partial.message, /Publish public key/); assert.equal(JSON.parse(m2.files.get(P.adminKey).text).keys.length, 2, 'the new key pair was saved');
  const fixed = await R.publishPublicKeyRepo({ ...s2, io: R.repoIOFrom(m2), unlocked: (await R.unlockAnalyticsRepo(R.repoIOFrom(m2), BASE, PW)).session.unlocked }); assert.equal(fixed.ok, true);
});
async function usageDataset(io) {
  const send = (iso, evs) => sinkAt(io, at(iso)).send(evs.map((e) => ({ ...e, ts: at(iso) + (e.dt || 0) })).map(({ dt, ...x }) => x)); const A = (o) => ev({ uid: UID('a'), ...o }); const B = (o) => ev({ uid: UID('b'), ...o }); const C2 = (o) => ev({ uid: UID('c'), ...o });
  await send('2026-09-10T10:00:00Z', [A({ sid: SID(41) }), A({ t: 'active', sid: SID(41), ms: 50_000, dt: 50_000 })]); await send('2026-09-12T10:00:00Z', [A({ sid: SID(42) }), A({ t: 'feature', f: 'about', sid: SID(42) })]); await send('2026-09-20T10:00:00Z', [B({ sid: SID(43), ver: '17.7.3' }), B({ t: 'generation', k: 'cr', ok: false, sid: SID(43), ver: '17.7.3' })]);
  await send('2026-10-12T10:00:00Z', [A({ sid: SID(44) }), A({ t: 'generation', k: 'describe-read-only', ok: true, rv: true, sid: SID(44) })]); await send('2026-10-31T23:50:00Z', [C2({ sid: SID(45) }), C2({ t: 'active', sid: SID(45), ms: 300_000, dt: 300_000 })]);
  await send('2026-11-01T00:20:00Z', [C2({ t: 'active', sid: SID(45), ms: 300_000, dt: 600_000 }), C2({ t: 'feature', f: 'sync', sid: SID(45) })]); await send('2026-11-05T09:00:00Z', [B({ sid: SID(46) }), B({ t: 'feature', f: 'about', sid: SID(46) })]); await send('2026-11-09T09:00:00Z', [A({ sid: SID(47) }), A({ t: 'feature', f: 'quick-start', sid: SID(47) })]);
}
test('V17.7.4 compaction — old months become encrypted roll-ups, their batch files are removed, and the dashboard is IDENTICAL before and after; running it again changes nothing; the current month and unreadable files are left alone', async () => {
  const { mem, io, session } = world(); await usageDataset(io); mem.files.set(`${BASE}/events/2026-09-10/${'9'.repeat(32)}.json`, { text: 'damaged', sha: 'dmg' }); const NOW = at('2026-11-09T12:00:00Z'); const before = strictSummary(await R.loadSummaryRepo(session, '2026-09-01', '2026-11-09', NOW, 400)); assert.equal(before.kpi.totalSessions, 7, 'the session across the month end is counted once'); assert.equal(before.kpi.uniqueUsers, 3);
  const rawBefore = files(mem, `${BASE}/events`).length; const progress = []; const r = await R.compactRepo(session, NOW, 400, (t) => progress.push(t)); assert.equal(r.ok, true, JSON.stringify(r)); assert.deepEqual(r.report.daysCompacted, ['2026-09-10', '2026-09-12', '2026-09-20', '2026-10-12', '2026-10-31', '2026-11-01', '2026-11-05']); assert.equal(r.report.filesMerged, 7); assert.equal(r.report.filesDeleted, 7); assert.equal(r.report.rollupsWritten, 3); assert.equal(r.report.skippedUnreadable, 1); assert.ok(progress.length >= 2);
  assert.deepEqual(files(mem, `${BASE}/rollups`).map((f) => f.split('/').pop()).sort(), ['2026-09.json', '2026-10.json', '2026-11.json']); assert.ok(mem.files.has(`${BASE}/events/2026-09-10/${'9'.repeat(32)}.json`), 'the unreadable file stays, untouched'); assert.equal(files(mem, `${BASE}/events`).length, 2, 'only the unreadable file and today\'s batch remain raw (today is not compacted)'); assert.ok(files(mem, `${BASE}/events`).length < rawBefore);
  const roll = [...mem.files.entries()].filter(([k]) => k.includes('/rollups/')).map(([k, v]) => v.text).join(''); for (const w of ['2026-09', 'about', 'quick', UID('a'), 'sessions', 'merged']) assert.ok(!roll.includes(w), `"${w}" is not readable in a roll-up`);
  const after = strictSummary(await R.loadSummaryRepo({ ...session, cache: new Map() }, '2026-09-01', '2026-11-09', NOW, 400)); const dropDamaged = (x) => x; assert.deepEqual(dropDamaged(after), before, 'the dashboard is identical after compaction'); const again = await R.compactRepo(session, NOW, 400); assert.equal(again.ok, true); assert.equal(again.report.filesMerged, 0); assert.equal(again.report.filesDeleted, 0); assert.deepEqual(strictSummary(await R.loadSummaryRepo({ ...session, cache: new Map() }, '2026-09-01', '2026-11-09', NOW, 400)), before, 'idempotent');
  const wk = strictSummary(await R.loadSummaryRepo({ ...session, cache: new Map() }, '2026-10-26', '2026-11-09', NOW, 400)); assert.equal(wk.kpi.totalActiveMs, 600_000);
});
test('V17.7.4 compaction — an interrupted run (a delete fails halfway) never double counts: the merged batch files are remembered inside the roll-up; the next run finishes; retention removes data beyond the period; the budget per run is respected', async () => {
  const { mem, io, session } = world(); await usageDataset(io); const NOW = at('2026-11-09T12:00:00Z'); const before = strictSummary(await R.loadSummaryRepo(session, '2026-09-01', '2026-11-09', NOW, 400)); let n = 0; const flaky = { ...io, remove: async (p, s, m) => { n += 1; if (n === 3) throw new G.RepositoryError('x', 'network'); return io.remove(p, s, m); } };
  const r = await R.compactRepo({ ...session, io: flaky, cache: new Map() }, NOW, 400); assert.equal(r.ok, false); assert.equal(r.kind, 'partial'); assert.match(r.message, /already merged/); const mid = strictSummary(await R.loadSummaryRepo({ ...session, cache: new Map() }, '2026-09-01', '2026-11-09', NOW, 400)); assert.deepEqual(mid, before, 'half merged, half still raw — and not one event counted twice');
  const done = await R.compactRepo(session, NOW, 400); assert.equal(done.ok, true); assert.equal(strictSummary(await R.loadSummaryRepo({ ...session, cache: new Map() }, '2026-09-01', '2026-11-09', NOW, 400)).kpi.totalSessions, before.kpi.totalSessions);
  const w2 = world(); await usageDataset(w2.io); const ret = await R.compactRepo(w2.session, NOW, 30, () => undefined); assert.equal(ret.ok, true); const kept = strictSummary(await R.loadSummaryRepo({ ...w2.session, cache: new Map() }, '2026-09-01', '2026-11-09', NOW, 400)); assert.equal(kept.kpi.totalSessions, 4, 'September is older than 30 days: removed without being kept; October (from the 10th) and November stay'); assert.equal(files(w2.mem, `${BASE}/events`).filter((f) => f.includes('/2026-09-')).length, 0);
  const many = world(); for (let i = 0; i < 310; i += 1) many.mem.files.set(`${BASE}/events/2026-08-15/${String(i).padStart(32, '0')}.json`, { text: 'junk', sha: `s${i}` }); const big = await R.compactRepo(many.session, NOW, 400); assert.equal(big.ok, true); assert.equal(big.report.remaining, true, 'a run is bounded (300 files); it says so'); assert.equal(big.report.skippedUnreadable, 300);
});
test('V17.7.4 repository connections — without listing / deleting (central access) the dashboard and compaction say so plainly; without a connection every action says no repository; analytics never throws', async () => {
  const noList = R.repoIOFrom({ describe: 'central', read: async () => null, write: async () => 'x' }); assert.equal((await R.loadSummaryRepo({ io: noList, base: BASE, unlocked: ADMIN, adminSha: '', cache: new Map() }, '2026-11-01', '2026-11-09', Date.now(), 400)).kind, 'unsupported'); assert.match(R.REPO_MESSAGES.unsupported, /personal GitHub access token/);
  assert.equal((await R.compactRepo({ io: noList, base: BASE, unlocked: ADMIN, adminSha: '', cache: new Map() }, Date.now(), 400)).kind, 'unsupported'); assert.equal(R.repoIOFrom(null), null);
  for (const k of Object.keys(R.REPO_MESSAGES)) { const m = R.REPO_MESSAGES[k]; assert.ok(m.length > 10 && !/password:|token:|[A-Za-z0-9_-]{40,}/.test(m), k); } assert.equal(R.REPO_MESSAGES['invalid-password'], 'Invalid administrator password');
  assert.equal(R.validAnalyticsPath('sql-assistant-data/analytics'), true); for (const bad of ['analytics', '/sql-assistant-data/x', 'sql-assistant-data/../x', 'sql-assistant-data/.hidden', 'sql-assistant-data/a b', 'sql-assistant-data/', 'sql-assistant-data/x/', `sql-assistant-data/${'a'.repeat(120)}`, 5, null]) assert.equal(R.validAnalyticsPath(bad), false, String(bad));
});

