  assert.equal((src('src/ui/pages/analyticsRepoPanel.ts').match(/\.value = ''/g) || []).length >= 3, true, 'password fields are emptied');
  for (const f of ['dist/index.html', 'index.html', 'release/index.html']) if (existsSync(join(root, f))) { const h = src(f); for (const v of [PW, PW2, 'SYNTHETIC-', 'ZZ-PRIVATE']) assert.ok(!h.includes(v), `${f}: no ${v}`); assert.ok(!/-----BEGIN [A-Z ]*PRIVATE KEY/.test(h), `${f}: no PEM`); assert.ok(h.includes('sqla-analytics-admin-key'), `${f}: contains the provider`); }
