  assert.match(rt, /function analyticsIO\(\) \{ if \(!secrets\.githubToken && !brokerEnabled\(\) && !hasRepositoryOverride\(\)\) return null;/, 'no connection ⇒ no repository (the published read-only copy is never used for writing)'); assert.match(rt, /Invalid administrator password|ADMIN_MESSAGES\.invalid/); assert.ok(!/await\s+startAnalytics/.test(strip(src('src/main.ts'))));
