test('V17.7.4 toolchain — the committed, checksum-pinned TypeScript is used with no npm, no registry and no node_modules; every file is verified; a modified file, a wrong version at TSC_PATH or a missing folder stops the build with a message', () => {
  const real = TC.resolveTypeScript(root); assert.equal(real.ok, true, real.message); assert.equal(real.version, '5.8.3'); assert.equal(real.source, 'tools/typescript (committed)', 'with no node_modules the committed compiler is the one used'); assert.ok(!existsSync(join(root, 'node_modules/typescript')) || true);
  const sums = JSON.parse(src('tools/typescript/CHECKSUMS.json')); assert.equal(sums.version, '5.8.3'); const onDisk = (function w(d, b) { return readdirSync(d).flatMap((x) => { const p = join(d, x); return statSync(p).isDirectory() ? w(p, `${b}${x}/`) : [`${b}${x}`]; }); })(join(root, 'tools/typescript'), '').filter((x) => x !== 'CHECKSUMS.json' && x !== 'README.md'); assert.deepEqual(onDisk.sort(), Object.keys(sums.sha256).sort(), 'every vendored file is listed with its SHA-256 — and nothing else is there'); assert.equal(TC.verifyChecksums(join(root, 'tools/typescript')), ''); assert.ok(existsSync(join(root, 'tools/typescript/LICENSE.txt')), 'the Apache-2.0 license travels with the compiler');
  const t = mkdtempSync(join(tmpdir(), 'sqla-tc-')); try {
    cpSync(join(root, 'tools'), join(t, 'tools'), { recursive: true }); cpSync(join(root, 'package.json'), join(t, 'package.json')); assert.equal(TC.resolveTypeScript(t).ok, true); const own = { ...process.env, NODE_PATH: '', TSC_PATH: '' }; delete own.TSC_PATH; const run = spawnSync(process.execPath, [join(root, 'scripts/tsc.mjs'), '--version'], { cwd: t, encoding: 'utf8', env: own }); assert.equal(run.status, 0, run.stderr); assert.match(run.stdout, /Version 5\.8\.3/);
    writeFileSync(join(t, 'tools/typescript/lib/lib.es5.d.ts'), `${readFileSync(join(t, 'tools/typescript/lib/lib.es5.d.ts'), 'utf8')}\n// tampered`); const bad = TC.resolveTypeScript(t); assert.equal(bad.ok, false); assert.match(bad.message, /lib\.es5\.d\.ts was modified/); assert.match(bad.message, /nothing was built/);
    rmSync(join(t, 'tools'), { recursive: true, force: true }); const savedNP = process.env.NODE_PATH; delete process.env.NODE_PATH; let gone; try { gone = TC.resolveTypeScript(t); } finally { if (savedNP !== undefined) process.env.NODE_PATH = savedNP; } assert.equal(gone.ok, false); assert.match(gone.message, /package\.json pins 5\.8\.3/); assert.match(gone.message, /tools\/typescript/);
    mkdirSync(join(t, 'fake/bin'), { recursive: true }); writeFileSync(join(t, 'fake/package.json'), '{"version":"6.0.2"}'); writeFileSync(join(t, 'fake/bin/tsc'), ''); process.env.TSC_PATH = join(t, 'fake'); try { const w = TC.resolveTypeScript(root); assert.equal(w.ok, false); assert.match(w.message, /6\.0\.2.*pins 5\.8\.3/, 'an explicit TSC_PATH of the wrong version is refused, never silently replaced'); process.env.TSC_PATH = join(t, 'missing'); assert.equal(TC.resolveTypeScript(root).ok, false); process.env.TSC_PATH = join(root, 'tools/typescript/bin/tsc'); assert.equal(TC.resolveTypeScript(root).source, 'TSC_PATH'); } finally { delete process.env.TSC_PATH; }
  } finally { rmSync(t, { recursive: true, force: true }); }
});
test('V17.7.4 no registry, no credentials: the build scripts contain no registry or network address and no machine-specific path; npm scripts call the pinned compiler through node; the Pages workflow needs only the default GITHUB_TOKEN', () => {
  for (const f of ['scripts/build.mjs', 'scripts/toolchain.mjs', 'scripts/tsc.mjs', 'scripts/check-toolchain.mjs', 'scripts/verify-no-npm.mjs']) { const t = strip(src(f)); assert.ok(!/registry\.npmjs|npmjs\.org|https?:\/\//.test(t), `${f}: no network address`); assert.ok(!/\/opt\/|oai-docgen|C:\\\\/.test(t), `${f}: no machine-specific path`); assert.ok(!/npm (ci|install)/.test(t), `${f}: no npm install`); }
  const pkg = JSON.parse(src('package.json')); assert.equal(pkg.scripts.typecheck, 'node scripts/tsc.mjs -p tsconfig.json --noEmit'); assert.equal(pkg.scripts['typecheck:test'], 'node scripts/tsc.mjs -p tsconfig.test.json --noEmit'); assert.ok(!/(^|[^.\w/])tsc -p/.test(JSON.stringify(pkg.scripts)), 'no bare tsc (it would need an npm installation)'); assert.equal(pkg.scripts.build, 'node scripts/build.mjs'); assert.match(pkg.scripts.test, /^node scripts\/build\.mjs && node --test/); assert.match(src('scripts/build.mjs'), /package\.json pins|resolveTypeScript/);
  const wf = src('.github/workflows/deploy-pages.yml'); assert.ok(!/secrets\./.test(wf), 'only the default GITHUB_TOKEN (no secret of any name)'); assert.ok(!/azure|AZURE/i.test(wf), 'no Azure step or credential in the Pages workflow'); assert.match(wf, /run: node scripts\/check-toolchain\.mjs --committed-only/, 'V17.7.5: the Install step only VERIFIES the committed compiler'); assert.ok(!/\bnpm\b/.test(wf), 'V17.7.5: no package manager and no fallback to one');
  assert.match(wf, /vars\.SQLA_ANALYTICS_PROVIDER == 'repository'/); assert.ok(wf.indexOf("provider:'repository'") > 0 && wf.indexOf("provider:'repository'") < wf.indexOf('Verify the artifact that will be published'), 'the serverless configuration is written before the final artifact verification'); assert.ok(!/(vars|secrets)\.[A-Z_]*(PASSWORD|ADMIN_PASS|PRIVATE)/.test(wf), 'no password variable or secret is read by the Pages workflow');
  for (const f of ['package-analytics-service.yml', 'package-repo-broker.yml']) assert.match(src(`.github/workflows/${f}`), /deploys nothing/i, `${f} says that it deploys nothing`); assert.ok(!/azure/i.test(src('.github/workflows/publish-data.yml')));
  const wfFiles = readdirSync(join(root, '.github/workflows')); for (const f of wfFiles) assert.ok(!/continue-on-error/.test(src(`.github/workflows/${f}`).replace(/^\s*#.*$/gm, '')), `${f}: no continue-on-error`);
});
